import {GEAR,SUPPLIES} from './data.js';
let sequence=0;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gear=id=>GEAR.find(item=>item.id===id);
const names={rod:'Hengel',reel:'Molen',line:'Hoofdlijn',indicator:'Beetmelder',terminal:'Lood / montage',hook:'Haak',bait:'Aas'};
const part=(field,body)=>`<g class="visual-part" data-visual-part="${field}" data-visual-index="0" role="button" tabindex="0" aria-controls="assembly-part-${field}" aria-label="${names[field]} aanpassen">${body}</g>`;
const callout=(field,number,label,x,y)=>`<button type="button" class="assembly-callout" style="--callout-x:${x}%;--callout-y:${y}%;--callout-inset:${(y*.28).toFixed(2)}px" data-visual-part="${field}" data-visual-index="0" aria-controls="assembly-part-${field}" aria-label="${names[field]} aanpassen"><span>${number}</span><strong>${label}</strong></button>`;
const wire=(path,x,y)=>`<path d="${path}"/><circle cx="${x}" cy="${y}" r="4"/>`;

function baitDrawing(rod){
 const color=SUPPLIES.find(item=>item.id===rod.bait)?.color||'#d6bf83';
 if(rod.bait==='corn')return `<g fill="#e2b94d" stroke="#f6d77c" stroke-width="1.3"><path d="M270 420q-11-7-16 5t5 15q13 0 11-20Z"/><path d="M274 423q12-7 15 5t-8 14q-11-2-7-19Z"/></g>`;
 if(['maggots','krill'].includes(rod.bait))return `<g fill="${rod.bait==='krill'?'#c68d76':'#e4d8b9'}" stroke="#a69c80" stroke-width="1"><ellipse cx="268" cy="428" rx="5" ry="13" transform="rotate(-28 268 428)"/><ellipse cx="277" cy="429" rx="5" ry="12" transform="rotate(16 277 429)"/><ellipse cx="285" cy="426" rx="4" ry="10" transform="rotate(40 285 426)"/><path d="M260 424l9 2m-7 3 10 2m1-8 8 1m-8 5 8 1" fill="none"/></g>`;
 if(['worms','bacon'].includes(rod.bait))return '<path d="M265 416c-19-9-14 25-1 15s22-18 20-1-18 18-14 6" fill="none" stroke="#bd8f7f" stroke-width="7" stroke-linecap="round"/>';
 if(['squid','fishbait'].includes(rod.bait))return `<path d="M260 419q22-17 30 4l-6 7 8 5-10-2q-14 12-22-14Z" fill="${color}" stroke="#d2c3a2" stroke-width="1.2"/>`;
 const radius=rod.baitSize==='large'?15:rod.baitSize==='small'?9:12;
 return `<circle cx="275" cy="429" r="${radius}" fill="${color}" stroke="#e1c18c" stroke-width="1.3"/><circle cx="271" cy="425" r="3" fill="#fff" opacity=".15"/><path d="M264 421l23 15" stroke="#9e8058" stroke-width="1" opacity=".6"/>`;
}

/** Bench drawing and a separate close-up keep the terminal tackle readable. */
export function assemblyDiagram(rod){
 const uid='assembly-'+(++sequence),method=rod.style,isFloat=method==='dobber',isCarp=method==='karper',isFeeder=method==='feeder';
 const premium=(gear(rod.rod)?.power||1)>2,metal=premium?'#b7c7bd':'#91a398',line=gear(rod.line),lineWidth=Math.min(2.4,1.2+Math.log2(line?.strength||3)*.15);
 const handle=`<path d="M2 0H106" stroke="#0a100c" stroke-width="23" stroke-linecap="round"/><path d="M5-2h72" stroke="${isCarp?'#586453':'#bba17a'}" stroke-width="18" stroke-linecap="round"/><path d="M8-9v15m9-17v18m9-18v18m9-18v18m9-18v18m9-18v18m9-18v18" stroke="${isCarp?'#273a2b':'#7e6c50'}" opacity=".7"/><path d="M92-9h23v18H92Z" fill="#242f28" stroke="#879b84"/><path d="M116 0H492Q558-1 607 12" stroke="#080f0b" stroke-width="8" fill="none"/><path d="M116-2H492Q558-3 607 10" stroke="${metal}" stroke-width="2.3" fill="none"/><path d="M490-1Q560-2 607 12" stroke="${isFeeder?'#d4be82':metal}" stroke-width="${isFeeder?2.6:1.7}" fill="none"/><path d="M307-5v9m116-9v9" stroke="#c5c9b0" stroke-width="4"/>`;
 const guides=[198,294,388,480,551,590].map((x,index)=>`<ellipse cx="${x}" cy="${index>3?index===5?8:1:-7}" rx="${5-index*.4}" ry="${8-index*.6}" fill="none" stroke="#b8c2ac" stroke-width="1.4"/>`).join('');
 const reel=`<path d="M121 1v23l22 12" fill="none" stroke="${metal}" stroke-width="7"/><path d="M128 26q-20 3-17 20l14 14 39-9 10-13-26-17Z" fill="#28392e" stroke="#7c8f7c" stroke-width="1.5"/><ellipse cx="150" cy="36" rx="20" ry="25" fill="#425441" stroke="#bcc6ad" stroke-width="2"/><path d="M137 17q27-10 28 16v18q-15 13-30 1Z" fill="url(#${uid}-spool)" stroke="#d0cfb0" stroke-width="1.4"/><path d="M137 25h27m-28 6h28m-28 6h28m-28 6h28" stroke="#1c3328" stroke-width="1.8" opacity=".8"/><path d="M125 17q-18 29 11 43" fill="none" stroke="#d9d8bd" stroke-width="2"/><path d="M164 50l20 14 15-5" stroke="#a8b5a1" stroke-width="4" fill="none"/><ellipse cx="204" cy="56" rx="11" ry="6" fill="#b9a17a" stroke="#6f6951"/><circle cx="149" cy="38" r="4" fill="#d5ccac"/>`;
 let indicator='';
 if(isFeeder&&rod.indicator)indicator='<g class="bell-swing"><path d="M494-5v-9m-6-2h14" stroke="#b5c5a2" stroke-width="2"/><path d="M485-15q-1-16 7-16t7 16Z" fill="#d4b972" stroke="#efd69a"/><circle cx="492" cy="-14" r="3" fill="#f4d687"/></g>';
 else if(!isFloat&&rod.indicator)indicator='<path d="M347 1v27m-14 18h29" stroke="#8c9f82" stroke-width="2"/><rect x="331" y="8" width="32" height="31" rx="5" fill="#314b3b" stroke="#9eb98a" stroke-width="2"/><circle cx="347" cy="17" r="4" fill="#d2ec8f"/><path d="M339 29h16" stroke="#71866a" stroke-width="2"/>';
 const rodWires=wire('M152 75V132L417 236',417,236)+wire('M498 43V100L598 142',598,142)+wire('M147 480H202L251 375',251,375)+(isFloat?'':wire(rod.indicator?(isFeeder?'M519 373V309L534 148':'M519 373V302L425 255'):'M519 373V275L651 126',rod.indicator?(isFeeder?534:425):651,rod.indicator?(isFeeder?148:255):126));
 const mainRod=`<svg class="rod-visual assembly-diagram" viewBox="0 0 720 480" xmlns="http://www.w3.org/2000/svg" role="group" aria-label="Hengel met molen en hoofdlijn"><defs><linearGradient id="${uid}-spool" x2="1" y2=".3"><stop stop-color="#6c7e61"/><stop offset=".45" stop-color="#c2c3a0"/><stop offset="1" stop-color="#677d68"/></linearGradient><pattern id="${uid}-grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#bed1b3" stroke-opacity=".045"/></pattern></defs><rect width="720" height="480" fill="url(#${uid}-grid)"/><ellipse cx="355" cy="316" rx="280" ry="30" transform="rotate(-28 355 316)" fill="#000" opacity=".18"/><g class="assembly-connectors">${rodWires}</g><g transform="translate(110 400) rotate(-28)">${part('rod',handle)}${part('line',`<path d="M151 16L198-7 294-7 388-7 480-7 551 1 590 8 607 12" stroke="#d0d9be" stroke-width="${lineWidth}" fill="none"/>${guides}`)}${part('reel',reel)}${indicator?part('indicator',indicator):''}</g><path d="M651 126l28-13" stroke="#8eaa95" stroke-width="1.5" stroke-dasharray="3 4"/></svg>`;
 const rigTitle=isFeeder?'Voerkorf & onderlijn':isFloat?'Dobber, lood & onderlijn':isCarp?'Lood & hair-rig':'Lood & zeemontage';
 let weight;
 if(isFeeder)weight=`<g><circle cx="255" cy="134" r="5" fill="none" stroke="#b5c1a9" stroke-width="2"/><rect x="232" y="144" width="47" height="64" rx="6" fill="#9b9865" opacity=".72"/><path d="M234 150h43m-43 12h43m-43 12h43m-43 12h43m-43 12h43m-36-52v59m10-59v59m10-59v59m10-59v59" stroke="#d2c79c" stroke-width="1.8"/><rect x="229" y="200" width="53" height="12" rx="4" fill="#63756a" stroke="#a8b9a3" stroke-width="1.5"/><path d="M255 137v7m0 68v16" stroke="#c7cdb3" stroke-width="2"/></g>`;
 else if(isFloat)weight='<path d="M255 113v-42" stroke="#cfb377" stroke-width="4"/><path d="M255 82V49" stroke="'+(rod.indicator?'#d5ee8e':'#d9a37e')+'" stroke-width="6" stroke-linecap="round"/><ellipse cx="255" cy="143" rx="11" ry="31" fill="#5b6846" stroke="#c5b986" stroke-width="2"/><path d="M244 130h22" stroke="#d5be89" stroke-width="6"/><path d="M255 174v66" stroke="#cbd5b8" stroke-width="2"/><g fill="#75877c" stroke="#bac5af" stroke-width="1.4"><circle cx="255" cy="198" r="6"/><circle cx="255" cy="217" r="5"/><circle cx="255" cy="236" r="4"/></g>';
 else weight='<path d="M255 133c-12 20-36 41-34 67 2 34 65 34 68 0 2-26-22-47-34-67Z" fill="url(#'+uid+'-lead)" stroke="#a8b5a3" stroke-width="2"/><path d="M241 167q-14 28 0 40" fill="none" stroke="#d5d4b6" opacity=".3" stroke-width="3"/><circle cx="255" cy="127" r="5" fill="none" stroke="#c3cdb3" stroke-width="2"/><path d="M255 220v17" stroke="#c3cdb3" stroke-width="2"/>';
 const leader=`<path d="M255 ${isFloat?240:isFeeder?228:237}V246" stroke="#c3cdb3" stroke-width="2"/><ellipse cx="255" cy="254" rx="4" ry="8" fill="none" stroke="#b7c4ad" stroke-width="2"/><circle cx="255" cy="265" r="3" fill="none" stroke="#b7c4ad" stroke-width="1.5"/><path class="assembly-leader" d="M255 269C257 295 300 303 295 332S273 364 271 376" fill="none" stroke="#b9cea6" stroke-width="2.6"/><path d="M255 270C259 296 301 305 295 334" fill="none" stroke="#718d78" stroke-width=".9" stroke-dasharray="4 3"/>`;
 const hook=`<circle cx="271" cy="381" r="4" fill="none" stroke="#d4d8c7" stroke-width="2.2"/><path d="M271 386v25c0 27-39 28-39 4v-8l9 11" fill="none" stroke="#17291f" stroke-width="7" stroke-linecap="round"/><path d="M270 386v25c0 25-37 27-37 4v-7l8 10" fill="none" stroke="#d6dcc9" stroke-width="3.3" stroke-linecap="round"/><path d="M235 408l4 2" stroke="#d6dcc9" stroke-width="2"/>`;
 const bait=`${isCarp?'<path d="M242 427q12 21 30 5" fill="none" stroke="#c6cfb3" stroke-width="1.4"/>':''}${baitDrawing(rod)}`;
 const rigWires=wire(isFloat?'M80 207H182L255 217':'M80 160H175L232 177',isFloat?255:232,isFloat?217:177)+wire('M79 348H186L237 417',237,417)+wire('M80 449H182L275 429',275,429)+(isFloat?wire('M80 71H167L247 133',247,133):'');
 const closeup=`<svg class="rod-visual assembly-rig-diagram" viewBox="0 0 380 480" xmlns="http://www.w3.org/2000/svg" role="group" aria-label="Vergrote montage met lood, onderlijn, haak en aas"><defs><linearGradient id="${uid}-lead" x2="1" y2=".3"><stop stop-color="#57695f"/><stop offset=".42" stop-color="#839582"/><stop offset="1" stop-color="#41574b"/></linearGradient></defs><g class="assembly-connectors">${rigWires}</g>${part('line',`<path d="M255 20v${isFloat?30:isFeeder?109:102}" fill="none" stroke="#ccdac0" stroke-width="3"/><circle cx="255" cy="20" r="3" fill="#aabe99"/>`)}${isFloat?part('indicator',weight):part('terminal',weight)}${part('terminal',leader)}${part('hook',hook)}${part('bait',bait)}<path d="M296 322h28" class="assembly-leader-pointer" stroke="#8ea589" stroke-width="1"/></svg>`;
 return `<div class="assembly-drawing-grid"><figure class="assembly-rod-figure"><figcaption><span>${isFloat?'01 — 03':'01 — 04'}</span><strong>Je hengel</strong></figcaption><div class="assembly-illustration assembly-rod-drawing">${mainRod}${callout('rod','01','HENGEL',4,8)}${callout('line','03','HOOFDLIJN',62,2)}${callout('reel','02','MOLEN',8,90)}${!isFloat?callout('indicator','04',rod.indicator?'BEETMELDER':'BEETMELDING',60,74):''}</div></figure><figure class="assembly-rig-figure"><figcaption><span>${isFloat?'04 — 07':'05 — 07'}</span><strong>${rigTitle}</strong><small>Uitvergroot</small></figcaption><div class="assembly-illustration assembly-rig-drawing">${closeup}${isFloat?callout('indicator','04','DOBBER',3,10):''}${callout('terminal','05',isFloat?'LOOD':isFeeder?'VOERKORF':'LOOD',3,isFloat?38:28)}${callout('hook','06','HAAK',3,68)}${callout('bait','07','AAS',3,89)}<button type="button" class="assembly-leader-label" data-visual-part="terminal" data-visual-index="0" aria-controls="assembly-part-terminal">Onderlijn</button></div></figure></div>`;
}
